test('reader-abort',async ()=>{const r=new FileReader(),events=[];for(const t of ['loadstart','progress','load','loadend','abort','error'])r.addEventListener(t,()=>events.push(t));r.readAsText(new Blob(['synthetic']));r.abort();log('immediate',stateLine(r),events.join(','));await new Promise(resolve=>setTimeout(resolve,30));log('later',stateLine(r),events.join(','))});
